<?php
namespace App\Console\Commands;
use Illuminate\Console\Command; use App\Services\EtfDataService; use App\Models\AppSetting;
class FetchEtfData extends Command { protected $signature='etf:fetch {--account= : Override account amount for this run}'; protected $description='Fetch real TWSE ETF dividend and quote data and analyze the strategy'; public function handle(EtfDataService $service): int { config(['etf.account_amount'=>(float)AppSetting::getValue('account_amount', config('etf.account_amount'))]); if($this->option('account')!==null){config(['etf.account_amount'=>(float)$this->option('account')]); AppSetting::setValue('account_amount',(float)$this->option('account'));} $this->info('Fetching TWSE ETF data...'); try{$result=$service->sync();$this->table(['Metric','Value'],[['Dividends',$result['dividends']],['Candidates',$result['candidates']],['Quotes',$result['quotes']],['Analyzed',$result['analyzed']],['Errors',count($result['errors'])]]); foreach($result['errors'] as $e)$this->warn($e);return self::SUCCESS;}catch(\Throwable $e){$this->error($e->getMessage());return self::FAILURE;} } }
